fun main() {
    val r = Regex("(\\d+)-(\\d+)")
    println(r.matches("12-34"))
    val m = r.find("tel 555-1234 x")!!
    println(m.value + " " + m.groupValues + " " + m.range)
    println(r.replace("1-2 and 3-4", "$2:$1"))
    println("a1b22c333".replace(Regex("\\d+")) { "<" + it.value.length + ">" })
    println("a, b;c".split(Regex("[,;]\\s*")))
    println(Regex("[aeiou]").findAll("education").map { it.value }.toList())
    val d = Regex("(?<y>\\d{4})-(?<mo>\\d{2})").find("on 2024-05-17")!!
    println(d.groups["y"]?.value + "/" + d.groups["mo"]!!.value)
    val (a, b) = Regex("(\\w+)@(\\w+)\\.com").matchEntire("joe@site.com")!!.destructured
    println(a + " " + b)
    println("Hello World".replace(Regex("o", RegexOption.IGNORE_CASE), "0"))
    println(Regex("^abc$", RegexOption.MULTILINE).findAll("abc\nabc").count())
    println(Regex("a.c").matches("a\nc"))
    println(Regex("a.c", RegexOption.DOT_MATCHES_ALL).matches("a\nc"))
    println(Regex("(a|ab)(c|bcd)(d*)").find("abcd")!!.groupValues)
    println(Regex("(?i)hello").containsMatchIn("say HELLO"))
    println(Regex("\\bfoo\\b").findAll("foo food foo").count())
    println(Regex("(\\w)\\1").find("hello")!!.value)
    println(Regex("\\w+(?=!)").find("hi there!")!!.value)
    println(Regex("(?<!\\d)\\d{2}(?!\\d)").findAll("1 22 333 44").map { it.value }.toList())
    println(Regex("(?<=\\$)\\d+").find("cost \$42")!!.value)
    println(Regex("a*?b").find("aaab")!!.value + Regex("a+?").find("aaa")!!.value)
    println(Regex("(ab)+").find("xababab")!!.value)
    println(Regex("x*").findAll("axb").map { it.range.toString() }.toList())
    println("2021-03-04".split(Regex("-"), 2))
    println(Regex.escape("a.b*c") + " " + "a.b".toRegex().pattern)
    println(Regex("[\\w.]+@[\\w.]+").findAll("a.b@c.d, e@f.g").map { it.value }.toList())
    println("abc" matches Regex("[a-c]+"))
    println("The Quick".replace(Regex("(\\w)(\\w*)")) { it.groupValues[1].lowercase() + it.groupValues[2].uppercase() })
    println("aaa".replace(Regex("a{2}"), "b"))
    println(Regex("\\p{Upper}\\p{Lower}+").findAll("Hello World").map { it.value }.toList())
    println("a b".replace(Regex("\\s"), "\\\\"))
    println(Regex("(a)|(b)").find("b")!!.groupValues)
    println(Regex("(a)|(b)").find("b")!!.groups[1])
    println("x".replace(Regex("(?:)"), "-"))
}
